<script setup>
import { computed, nextTick, ref } from 'vue';
const activeTab = ref('Assign');
const classTabs = ['Roster', 'Groups', 'Student Library', 'Assign'];
const passages = [
  { id: 'demo', wordCount: '49', title: 'A Morning in the Garden', detail: 'A short story about discovery · 49 words' },
  { id: 'park-caretaker-qa', wordCount: '360', title: "Let’s Meet a Park Caretaker", detail: 'Community and nature · 360 words' },
  { id: 'pride-and-prejudice', wordCount: '1,156', title: 'Excerpt from Pride and Prejudice', detail: 'Classic literature · Jane Austen · 1,156 words' },
];
function read(key, fallback) { try { const value = JSON.parse(localStorage.getItem(key)); return Array.isArray(value) ? value : fallback; } catch { return fallback; } }
const roster = ref(read('soundworks.roster', ['Alex', 'Jordan', 'Sam', 'Taylor']));
const assignments = ref(read('soundworks.assignments', []));
const selected = ref([]);
const passage = ref(new URLSearchParams(location.search).get('passage') || '');
if (!passages.some(p => p.id === passage.value)) passage.value = '';
const search = ref(passages.find(p => p.id === passage.value)?.title || '');
const searching = ref(!passage.value);
const searchInput = ref(null);
const changeButton = ref(null);
const selectedReading = computed(() => passages.find(p => p.id === passage.value));
function changeReading() { search.value = ''; searching.value = true; nextTick(() => searchInput.value?.focus()); }
const readingResults = computed(() => {
  const query = search.value.trim().toLocaleLowerCase();
  return passages.filter(p => !query || p.title.toLocaleLowerCase().includes(query) || p.detail.toLocaleLowerCase().includes(query));
});
function searchReadings() { passage.value = ''; searching.value = true; }
function selectReading(reading) { passage.value = reading.id; search.value = reading.title; searching.value = false; nextTick(() => changeButton.value?.focus()); }
const audio = ref(true);
const due = ref('');
const studentSearch = ref('');
const filteredStudents = computed(() => roster.value.filter(student => student.toLocaleLowerCase().includes(studentSearch.value.trim().toLocaleLowerCase())));
const status = ref('');
const error = ref('');
const allSelected = computed(() => roster.value.length > 0 && selected.value.length === roster.value.length);
function save(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch { error.value = 'Your browser could not save this change. Check storage settings and try again.'; return false; } }
function assign() {
  error.value = ''; status.value = '';
  if (!passage.value) { error.value = 'Choose a reading from the search results.'; return; }
  if (!selected.value.length) { error.value = 'Choose at least one student.'; return; }
  const item = { id: crypto.randomUUID(), passage: passage.value, students: [...selected.value], audio: audio.value, due: due.value, created: new Date().toISOString() };
  const next = [item, ...assignments.value];
  if (save('soundworks.assignments', next)) { assignments.value = next; status.value = `Assigned to ${item.students.length} student${item.students.length === 1 ? '' : 's'}. Share the reading link below.`; selected.value = []; }
}
function link(item) {
  const url = new URL(location.pathname, location.origin);
  url.searchParams.set('passage', item.passage);
  url.searchParams.set('audio', item.audio ? 'on' : 'off');
  return url.href;
}
async function copy(item) { try { await navigator.clipboard.writeText(link(item)); status.value = 'Reading link copied.'; } catch { error.value = 'Could not copy. Open the reading and copy its address instead.'; } }
function remove(item) { const next = assignments.value.filter(a => a.id !== item.id); if (save('soundworks.assignments', next)) assignments.value = next; }
const title = id => passages.find(p => p.id === id)?.title || id;
</script>
<template>
  <div class="class-admin-shell">
  <header class="admin-header"><div class="admin-nav-inner"><a class="admin-logo" href="/">ReadWorks<sup>®</sup></a><nav class="admin-primary" aria-label="Main navigation"><span>Content</span><span>My Tools</span><span>Assignments &amp; Progress</span><span class="active">Class Admin</span></nav><div class="admin-secondary"><span>Alignments</span><span>Teacher Guide</span><span>Professional Learning</span><span>Help</span><span>Iron <span class="down-caret"></span></span></div></div></header>
  <section class="class-heading"><div class="class-heading-inner"><div class="class-heading-row"><div><h1>hklhjk</h1><p>1ST GRADE</p></div><div class="class-static-actions"><span>Create a Class</span><span>Options <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 9 7 7 7-7"/></svg></span></div></div><nav class="class-tabs" aria-label="Class administration"><button v-for="tab in classTabs" :key="tab" type="button" :class="{ active: activeTab === tab }" :aria-current="activeTab === tab ? 'page' : undefined" @click="activeTab = tab">{{ tab }}</button></nav></div></section>
  <main v-if="activeTab === 'Assign'" class="teacher-page">
    <div class="teacher-grid">
      <form class="teacher-card assignment-form" @submit.prevent="assign">
        <h2>Create an assignment</h2>
        <fieldset><legend><span class="step">1</span> Choose a reading</legend>
          <div v-if="selectedReading && !searching" class="chosen-reading"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg><div><strong>{{ selectedReading.title }}</strong><small>{{ selectedReading.wordCount }} words</small></div><button ref="changeButton" type="button" @click="changeReading">Change</button></div>
          <div v-else class="reading-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg><input ref="searchInput" type="search" aria-label="Search readings" placeholder="Search by title or author" v-model="search" @input="searchReadings" @focus="searching = true" @keydown.esc="searching = false" autocomplete="off" aria-controls="reading-results"></div>
          <div v-if="searching" id="reading-results" class="reading-results"><button v-for="reading in readingResults" :key="reading.id" type="button" :class="{ 'is-selected': passage === reading.id }" @click="selectReading(reading)"><strong>{{ reading.title }}</strong><small>{{ reading.detail }}</small></button><p v-if="!readingResults.length" role="status">No readings found. Try another title or author.</p></div>
        </fieldset>
        <fieldset><legend><span class="step">2</span> Set reading support</legend><div class="support-options"><label :class="{ chosen: audio }"><input type="radio" name="support" :value="true" v-model="audio"><strong>With audio</strong></label><label :class="{ chosen: !audio }"><input type="radio" name="support" :value="false" v-model="audio"><strong>Without audio</strong></label></div></fieldset>
        <fieldset><legend><span class="step">3</span> Choose students</legend><label class="select-all"><input type="checkbox" :checked="allSelected" @change="selected = allSelected ? [] : [...roster]"> Select all <span>{{ selected.length }} selected</span></label><div class="reading-search student-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg><input type="search" aria-label="Search students" placeholder="Search students" v-model="studentSearch" autocomplete="off"></div><div class="student-grid"><label v-for="student in filteredStudents" :key="student" :class="{ 'is-selected': selected.includes(student) }"><input type="checkbox" :value="student" v-model="selected"><span class="avatar">{{ student.slice(0,1).toUpperCase() }}</span>{{ student }}</label></div><p v-if="!filteredStudents.length" class="no-students" role="status">No students found.</p></fieldset>
        <label class="due-date">Due date <span>(optional)</span><input type="date" v-model="due"></label>
        <p v-if="error" role="alert" class="teacher-error">{{ error }}</p><button class="assign-primary" type="submit">Assign reading</button>
      </form>
      <aside class="teacher-card assignment-summary"><h2>Your classroom</h2><div class="class-stats"><div><strong>{{ roster.length }}</strong><span>Students</span></div><div><strong>{{ assignments.length }}</strong><span>Assignments</span></div></div><hr></aside>
    </div>
    <section class="assignment-list"><div class="list-heading"><h2>Assigned readings</h2><span>{{ assignments.length }} total</span></div><p role="status" class="teacher-success" v-if="status">{{ status }}</p><div v-if="!assignments.length" class="empty-assignments"><h3>No assignments yet.</h3><p>Assigned readings will appear here.</p></div><article class="assignment-row" v-for="item in assignments" :key="item.id"><div><span class="audio-badge">{{ item.audio ? 'With audio' : 'Without audio' }}</span><h3>{{ title(item.passage) }}</h3><p>{{ item.students.join(', ') }}</p><small v-if="item.due">Due {{ item.due }}</small></div><div class="assignment-actions"><a :href="link(item)" target="_blank" rel="noopener">Open reading ↗</a><button @click="copy(item)">Copy link</button><button class="remove-assignment" @click="remove(item)" :aria-label="`Remove assignment: ${title(item.passage)}`">Remove</button></div></article></section>
  </main>
  <main v-else class="static-class-page"><section class="static-class-content">
    <template v-if="activeTab === 'Roster'"><div class="roster-toolbar"><p>1 Student. Click on the username to edit the student account or remove it from the class.</p><span class="static-teal-button">Add More Students</span></div><table class="roster-table"><thead><tr><th>STUDENT</th><th>PASSWORD</th><th>GROUP(S)</th><th>LAST LOGIN</th></tr></thead><tbody><tr><td><span class="student-name">Njnjk</span></td><td>Reset</td><td>-</td><td>Never</td></tr></tbody></table></template>
    <template v-else-if="activeTab === 'Groups'"><h2>Groups</h2><p>No groups have been created.</p></template>
    <template v-else><h2>Student Library</h2><p>Students can find readings in their library.</p></template>
    </section><aside class="student-help"><h2>How to get students to their assignments</h2><ol><li>Have students go to<br><strong>www.readworks.org/student</strong></li><li>Students enter class code <strong>UXJMDE</strong></li><li>Tell your students that their default password is <strong>1234</strong></li></ol><p><strong>Note:</strong> Students can change their passwords when they log in, and you can change student passwords on this page.</p><h2>Student Experience</h2><p><span class="static-link">Watch this video</span> to preview the student experience and <span class="static-link">share these resources</span> with your students to get them started.</p></aside></main>
  <footer class="admin-footer">Terms &nbsp; | &nbsp; Privacy &nbsp; | &nbsp; Licensing &nbsp; | &nbsp; Partners &nbsp; | &nbsp; About Us &nbsp; | &nbsp; Blog &nbsp; | &nbsp; Contact</footer>
  </div>
</template>
